#include <Wire.h>

const int MPU = 0x68;   // AD0 low: address 0x68
int16_t ax, ay, az, gx;

void wake() {
  Wire.beginTransmission(MPU);
  Wire.write(0x6B);     // PWR_MGMT_1: write 0 to wake the chip (it powers up asleep)
  Wire.write(0);
  Wire.endTransmission();
}

void readImu() {
  Wire.beginTransmission(MPU);
  Wire.write(0x3B);     // ACCEL_XOUT_H: 14 bytes from here are accel X, Y, Z, temperature, gyro X, Y, Z
  Wire.endTransmission(false);
  Wire.requestFrom(MPU, 14);
  ax = Wire.read() << 8 | Wire.read();
  ay = Wire.read() << 8 | Wire.read();
  az = Wire.read() << 8 | Wire.read();
  Wire.read(); Wire.read();   // the temperature: skipped
  gx = Wire.read() << 8 | Wire.read();
  Wire.read(); Wire.read(); Wire.read(); Wire.read();
}

const int BUZZER = 8;
unsigned long lastPrint = 0;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  wake();
  pinMode(13, OUTPUT);
  Serial.println("tilt alarm: beeps past 20 deg");
}

void loop() {
  readImu();
  float roll = atan2(ay, az) * 180.0 / PI;
  bool alarm = abs(roll) > 20;
  digitalWrite(13, alarm ? HIGH : LOW);
  if (alarm) tone(BUZZER, 2000); else noTone(BUZZER);
  if (millis() - lastPrint >= 1000) {
    lastPrint = millis();
    Serial.print("roll ");
    Serial.print(roll, 0);
    Serial.print(" deg");
    if (abs(roll) > 20) Serial.print(" ALARM");
    Serial.println();
  }
  delay(100);
}

